vec3 ApplyTiltShift(vec3 color, vec2 texcoord, float blurAmount, float center, float range) {
    float distance = abs(texcoord.y - center);
    float blurFactor = smoothstep(0.0, range, distance);
    vec3 blurredColor = vec3(0.0);
    for (float i = -4.0; i <= 4.0; i++) {
        for (float j = -4.0; j <= 4.0; j++) {
            vec2 offset = vec2(i, j) * 0.002 * blurFactor * blurAmount;
            blurredColor += texture(iChannel0, texcoord + offset).rgb;
        }
    }
    return mix(color, blurredColor / 81.0, blurFactor);
}
vec3 ApplyLiquidEffect(vec3 color, vec2 texcoord, float time) {
    float wave = sin(texcoord.x * 10.0 + time * 5.0) * 0.03;
    vec2 offset = vec2(wave, 0.0);
    return texture(iChannel0, texcoord + offset).rgb;
}

vec3 ApplyDepthOfField(vec3 color, vec2 texcoord, vec2 mousePos, float blurAmount, float range) {
    float distance = length(texcoord - mousePos);

    float blurFactor = smoothstep(0.0, range, distance);

    vec3 blurredColor = vec3(0.0);

    for (float i = -4.0; i <= 4.0; i++) {
        for (float j = -4.0; j <= 4.0; j++) {
            vec2 offset = vec2(i, j) * 0.002 * blurFactor * blurAmount;
            blurredColor += texture(iChannel0, texcoord + offset).rgb;
        }
    }

    return mix(color, blurredColor / 81.0, blurFactor);
}

vec3 Bloom(in vec2 texcoord,vec3 color,vec2 texs) {
    float intensity = 1.5;
    int radius = 5;
    float threshold = 0.4;
    float count = 0.0;

    for (int i = -radius; i <= radius; ++i) {
        for (int j = -radius; j <= radius; ++j) {
            vec2 offset = vec2(i, j) * intensity / texs;
            color += texture(iChannel0, texcoord + offset).rgb;
            count += 1.0;
        }
    }

    color /= count;

    return color;
}

vec3 ApplyColorShift(vec3 color, float time) {
    float rShift = sin(time * 0.5) * 0.5 + 0.5; 
    float gShift = cos(time * 0.5) * 0.5 + 0.5;
    float bShift = sin(time * 0.2) * 0.5 + 0.5;
    return vec3(color.r * rShift, color.g * gShift, color.b * bShift);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy);
    vec2 mousePos = iMouse.xy / iResolution.xy;

    float ModTime=mod(iTime*0.2,7.0);

    float pixelSize = 0.01;

    vec3 col = texture(iChannel0, uv).rgb;



    if(ModTime<1.0){
       ///>This Works With the mouse<///
       col=ApplyDepthOfField(col,uv,mousePos,1.5,0.4);
    }else if(ModTime<2.0){
       col = ApplyTiltShift(col, uv, 1.5, 0.5, 0.5);
    }else if(ModTime <3.0){
     uv = floor(uv / pixelSize) * pixelSize;
     col = texture(iChannel0, uv).rgb;
    }else if(ModTime<4.0){
     col=ApplyLiquidEffect(col,uv,iTime*0.5); 
    }else if(ModTime<5.0){
    vec2 distortionR = vec2(0.005, 0.0);
    vec2 distortionG = vec2(0.0, 0.005);
    vec2 distortionB = vec2(-0.005, -0.005);
    col.r = texture(iChannel0, uv + distortionR * 0.15).r;
    col.g = texture(iChannel0, uv + distortionG * 0.25).g;
    col.b = texture(iChannel0, uv + distortionB * 0.3).b;
    }else if(ModTime<6.0){
      col+=Bloom(uv,col,iResolution.xy);  
    }else if(ModTime<7.0){
       col=ApplyColorShift(col,iTime); 
    }

    fragColor = vec4(col, 1.0);
}

vec2 movingTiles(vec2 _st, float _zoom, float _speed) {
    _st *= _zoom;
    float time = iTime * _speed;
    if (fract(time) > 0.5) {
        if (fract(_st.y * 0.5) > 0.5) {
            _st.x += fract(time) * 2.0;
        } else {
            _st.x -= fract(time) * 2.0;
        }
    } else {
        if (fract(_st.x * 0.5) > 0.5) {
            _st.y += fract(time) * 2.0;
        } else {
            _st.y -= fract(time) * 2.0;
        }
    }
    return fract(_st)-0.5;
}

vec3 drawFlower(vec2 uv, float iTime) {
    uv = movingTiles(uv, 3.0, 0.2);

    float AtanUv = atan(uv.x, uv.y);
    float rotation = iTime * 0.1; 
    float angle = AtanUv + rotation;

    vec2 rotatedUv = vec2(cos(angle), sin(angle)) * length(uv);

    float a = length(cos(angle * 2.5 + iTime));
    float a_Outline = length(cos(angle * 2.5 + iTime));

    float distance0 = length(uv) * 3.0;
    float PointsInFlower = smoothstep(0.1, 0.1 - 0.1, voronoi(rotatedUv * 30.)); 
    float distance1 = length(uv) * 4.0;
    distance1 += PointsInFlower * 10.0;

    float distanceForOutline = length(uv) * 1.5;

    float Flower = smoothstep(distance0, distance0 + 0.1, sin(abs(a * 1.9)));
    float FlowerInside = smoothstep(distance1, distance1 + 0.1, sin(abs(a * 1.9)));

    float FlowerOutline = smoothstep(distanceForOutline - 0.1, distanceForOutline + 0.1, sin(abs(a_Outline * 1.9)));

    float radius = 2.0;
    float n = smoot2(vec2(5.0 * radius, 20.0 * a));
    n *= pow(n, 0.1);

    vec3 ColorNoise = vec3(0.5 + 0.5 * n, 0.2 + 0.8 * n, 0.1 + 0.9 * n);

    vec3 Flowers = Flower + FlowerInside * ColorNoise;

    vec3 col = vec3(1.000, 0.420, 0.980) * Flowers;
    col += FlowerOutline * vec3(0.000, 0.000, 0.000);

    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    col += drawFlower(uv, iTime);


    fragColor = vec4(col, 1.0);
}

float noise(vec2 p){
      return fract(sin(p.x*100.0+p.y * 6579.)*5647.0);
}
float smoot(vec2 uv){
    vec2 id = floor(uv);
    vec2 lv = fract(uv);
    lv = lv*lv*(3.-2. * lv);

    float bl = noise(id);
    float br = noise(id + vec2(1.0, 0.0));
    float tl = noise(id + vec2(0.0, 1.0));
    float tr = noise(id + vec2(1.0,1.0));

    float b = mix(bl, br, lv.x);
    float t = mix(tl, tr, lv.x);
    return mix(b, t, lv.y);

}
float smoot2(vec2 uv){
    float c = smoot(uv*4.);
    c += smoot(uv*8.)*.4;
    c += smoot(uv*16.)*.15;
    c += smoot(uv*32.)*.125;
    c += smoot(uv*64.)*.0625;

     return c /= 2.5;
}
float voronoi(vec2 uv) { 
    vec2 id = floor(uv); 
    vec2 f = fract(uv); 

    float minDist = 1.0;
    for (int i = -1; i <= 1; i++) {
        for (int j = -1; j <= 1; j++) {
            vec2 neighbor = vec2(i, j);
            vec2 randomOffset = vec2(noise(id + neighbor), noise(id + neighbor + vec2(0.5, 0.5)));
            vec2 diff = neighbor + vec2(randomOffset) - f;
            float dist = length(diff);
            minDist = min(minDist, dist);


        }       
    }


    return minDist;
}
